package com.shiphappens.logistics.repository; import com.shiphappens.logistics.entity.*; import java.util.*; import org.springframework.data.jpa.repository.*; public interface WebhookSubscriptionRepository extends JpaRepository<WebhookSubscription,Long>{ @Query("select w from WebhookSubscription w where w.active = true and (w.customer is null or w.customer = :customer)") List<WebhookSubscription> findActiveForCustomer(@org.springframework.data.repository.query.Param("customer") Customer customer); }
